// Alien nuerons - Raymarching gyroid
// Credits to Art of Code's gyroid tutorial on YT, tutorial is here: https://www.youtube.com/watch?v=-adHIyjIYgk&list=PLGmrMu-IwbgsVjE7SAtFaWyhZXyBjJNnO&index=7
// "Gyroid is a minimal surface: a surface that minimizes its area for a given boundary"

#define MAX_STEPS 100
#define MAX_DIST 100.
#define SURF_DIST .001
#define TAU 6.283185
#define PI 3.141592
#define S smoothstep
#define T iTime

mat2 Rot(float a) {
    float s=sin(a), c=cos(a);
    return mat2(c, -s, s, c);
}

float sdBox(vec3 p, vec3 s) {
    p = abs(p)-s;
	return length(max(p, 0.))+min(max(p.x, max(p.y, p.z)), 0.);
}

float sdGyroid(vec3 p, float scale, float thickness, float bias) {
    p *= scale;
        return abs(dot(sin(p), cos(p.zxy)) - bias) / scale - thickness;
}


vec3 Transform(vec3 p) {
    p.z -= iTime*.1;
    p.y -=.3;
    return p;
}

float GetDist(vec3 p) {
    p = Transform(p);

    float box = sdBox(p, vec3(1));

    float g1 = sdGyroid(p, 5.23, .03, 1.4);
    float g2 = sdGyroid(p, 10.76, .03, .3);
    float g3 = sdGyroid(p, 20.76, .03, .3);
    float g4 = sdGyroid(p, 35.76, .03, .3);
    float g5 = sdGyroid(p, 60.76, .03, .3);
    float g6 = sdGyroid(p, 101.72, .03, .3);
    float g7 = sdGyroid(p, 185.56, .03, .3);


    //float g = min(g1, g2); //union
    //float g = max(g1, -g2); //subtraction
    g1 -= g2*.3;
    g1 -= g3*.2;
    g1 += g4*.1;
    g1 += g5*.1;
        g1 += g6*.8;
    g1 += g7*.5;


    float d = g1*.9; 
    //float d = max(box, g1 * .8);

    return d;
}




float RayMarch(vec3 ro, vec3 rd) {
	float dO=0.;

    for(int i=0; i<MAX_STEPS; i++) {
    	vec3 p = ro + rd*dO;
        float dS = GetDist(p);
        dO += dS;
        if(dO>MAX_DIST || abs(dS)<SURF_DIST) break;
    }

    return dO;
}

vec3 GetNormal(vec3 p) {
    vec2 e = vec2(.005, 0);
    vec3 n = GetDist(p) - 
    vec3(GetDist(p-e.xyy), GetDist(p-e.yxy),GetDist(p-e.yyx));

    return normalize(n);
}

vec3 GetRayDir(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 
        f = normalize(l-p),
        r = normalize(cross(vec3(0,1,0), f)),
        u = cross(f,r),
        c = f*z,
        i = c + uv.x*r + uv.y*u;
    return normalize(i);
}

vec3 Background(vec3 rd) {
    vec3 col = vec3(0);
    float t = iTime;
    float y = rd.y *.5+.5;
    col += (1.-y)*vec3(0.4, 0.8, 1.)*1.5;

    float a = atan(rd.x, rd.z);
    float beams = (sin(a*10.+t) * sin(a*7.-t) * sin(a*3.+t));
    beams *= smoothstep(.8, .5, y);
    col += beams;
    col = max(col, 0.);
    col += smoothstep(.5, .0, y);

    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
	vec2 m = iMouse.xy/iResolution.xy;
    float t = iTime;
    vec3 ro = vec3(0, 0, -.03);
    ro.yz *= Rot(-m.y*PI+1.);
    ro.xz *= Rot(-m.x*TAU);

    vec3 lookat = vec3(0, 0, 0);
    vec3 rd = GetRayDir(uv, ro, lookat, .8);
    vec3 col = vec3(0);

    float d = RayMarch(ro, rd);

    if(d<MAX_DIST) {
        vec3 p = ro + rd * d;
        vec3 n = GetNormal(p);
        p = Transform(p);

        //vec3 r = reflect(rd, n);
        //float dif = dot(n, normalize(vec3(1,2,3)))*.5+.5;
        //col = vec3(dif);

        float dif = n.y*.5+.5;
        col += dif*dif;

        float g2 = sdGyroid(p, 10.76, .03, .3);
        col *= smoothstep(-.1, .1, g2); //dimmer

        float crackWidth = -0.02 + smoothstep(0., -.5, n.y) * .04;
        float cracks = smoothstep(crackWidth, -.03, g2);
        float g3 = sdGyroid(p+t*.1, 5.76, .03, .0);
        float g4 = sdGyroid(p+t*.05, 4.76, .03, .0);
        cracks *= g3*g4*20.+.2*smoothstep(.2, .0, n.y);


        col += cracks*vec3(0.1,0.2,1.)*3.;
    }
    //col *= 0.;
    //d = sdGyroid(vec3(uv.x, uv.y, iTime*.1), 20., .02, 0.);
    //col += d*10.;

    col = mix(col, Background(rd), smoothstep(0., 7., d));

    fragColor = vec4(col, 1.0);
}
